"use client";

import Link from "next/link";
import { hasAuthParams, useAuth } from "react-oidc-context";
import { useEffect, useState } from "react";
import { persistAuthArtifacts } from "@/services/auth";

export default function LoginPage() {
  const auth = useAuth();
  const [isRedirecting, setIsRedirecting] = useState(false);
  const [notice, setNotice] = useState<string | null>(null);
  const processingCallback = typeof window !== "undefined" && hasAuthParams();

  useEffect(() => {
    if (typeof window === "undefined") {
      return;
    }

    const storedNotice = localStorage.getItem("auth_notice");
    if (storedNotice === "logged_out") {
      setNotice("Signed out successfully.");
      localStorage.removeItem("auth_notice");
    }
    if (storedNotice === "session_expired") {
      setNotice("Session expired. Please sign in again.");
      localStorage.removeItem("auth_notice");
    }
    if (storedNotice === "signup_verified") {
      setNotice("Email verified. Continue by signing in.");
      localStorage.removeItem("auth_notice");
    }
  }, []);

  useEffect(() => {
    if (auth.isAuthenticated && auth.user?.access_token) {
      persistAuthArtifacts(auth.user.access_token, auth.user.id_token);
      window.location.replace("/dashboard");
    }
  }, [auth.isAuthenticated, auth.user?.access_token, auth.user?.id_token]);

  if (auth.isLoading || processingCallback || auth.activeNavigator || isRedirecting) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-slate-950">
        <div className="rounded-xl border border-slate-800 bg-slate-900/70 px-5 py-4 text-sm text-slate-200">
          Signing you in...
        </div>
      </div>
    );
  }

  return (
    <main className="relative min-h-screen overflow-hidden bg-slate-950 text-slate-100">
      <div className="pointer-events-none absolute inset-0 bg-[radial-gradient(circle_at_top_left,#1d4ed8_0%,transparent_35%),radial-gradient(circle_at_bottom_right,#0f766e_0%,transparent_30%)] opacity-40" />

      <div className="relative mx-auto grid min-h-screen w-full max-w-6xl grid-cols-1 items-center gap-10 px-6 py-10 lg:grid-cols-2">
        <section className="hidden lg:block">
          <p className="mb-4 inline-flex rounded-full border border-sky-400/30 bg-sky-500/10 px-3 py-1 text-xs font-semibold uppercase tracking-[0.2em] text-sky-200">
            Hiring Intelligence Platform
          </p>
          <h1 className="max-w-xl text-5xl font-semibold leading-tight">
            AI screening and interview workflows for modern recruiting teams.
          </h1>
          <p className="mt-5 max-w-lg text-base text-slate-300">
            Centralize candidate pipelines, automate resume analysis, and
            shorten time-to-hire with a secure cloud-native architecture.
          </p>
          <div className="mt-10 grid max-w-xl grid-cols-3 gap-4">
            <MetricCard label="Avg. Screening Time" value="-68%" />
            <MetricCard label="Resume Throughput" value="10k+/day" />
            <MetricCard label="Recruiter Adoption" value="92%" />
          </div>
        </section>

        <section className="mx-auto w-full max-w-md">
          <div className="rounded-2xl border border-slate-800 bg-slate-900/80 p-7 shadow-2xl shadow-black/30 backdrop-blur">
            <p className="mb-2 text-sm text-slate-400">Welcome back</p>
            <h2 className="text-3xl font-semibold text-white">Sign in</h2>
            <p className="mt-2 text-sm text-slate-400">
              Continue to your recruiter or candidate workspace.
            </p>

            {notice ? (
              <p className="mt-5 rounded-lg border border-emerald-400/20 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-200">
                {notice}
              </p>
            ) : null}
            {auth.error ? (
              <p className="mt-5 rounded-lg border border-rose-400/20 bg-rose-500/10 px-3 py-2 text-sm text-rose-200">
                {auth.error.message}
              </p>
            ) : null}

            <button
              onClick={async () => {
                try {
                  setIsRedirecting(true);
                  await auth.signinRedirect();
                } catch {
                  setIsRedirecting(false);
                }
              }}
              className="mt-6 inline-flex w-full items-center justify-center rounded-lg bg-sky-500 px-4 py-3 font-medium text-white transition hover:bg-sky-400 disabled:cursor-not-allowed disabled:opacity-70"
              disabled={isRedirecting}
            >
              {isRedirecting ? "Redirecting..." : "Login with AWS Cognito"}
            </button>

            <div className="mt-5 flex items-center justify-between text-sm">
              <span className="text-slate-400">New to the platform?</span>
              <Link href="/signup" className="font-medium text-sky-300 hover:text-sky-200">
                Create an account
              </Link>
            </div>
          </div>
        </section>
      </div>
    </main>
  );
}

function MetricCard({ label, value }: { label: string; value: string }) {
  return (
    <article className="rounded-xl border border-slate-800 bg-slate-900/60 p-4">
      <p className="text-xs text-slate-400">{label}</p>
      <p className="mt-2 text-lg font-semibold text-white">{value}</p>
    </article>
  );
}
